import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mul, add, vec2, texture as texNode } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide } = ctx.THREE;

  // Root container
  const root = new Group();

  // Apply any cinematic primitives defined in config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const { name, params } = prim;
      if (ctx.primitives[name]) {
        const instance = ctx.primitives[name](root, params);
        // store for cleanup
        (root.userData._primitiveInstances ??= []).push(instance);
      }
    }
  }

  // Determine atlas region (fallback to full texture)
  const atlas = config.atlasRegion ?? { x: 0, y: 0, width: 512, height: 320 };
  const aspect = atlas.width / atlas.height;

  // Plane geometry sized to atlas region aspect ratio
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // Basic node material, will receive texture node later
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; assign when ready
  let loadedTexture = null;
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      // Build UV transform for atlas region
      const uvNode = uv();
      const texSize = vec2(tex.image.width, tex.image.height);
      const regionSize = vec2(atlas.width, atlas.height);
      const regionOffset = vec2(atlas.x, atlas.y);
      const scaledUV = mul(uvNode, div(regionSize, texSize));
      const offsetUV = add(scaledUV, div(regionOffset, texSize));
      // Create texture node with transformed UVs
      const mapNode = texNode(tex, offsetUV);
      material.map = mapNode;
      material.needsUpdate = true;
    })
    .catch(() => {
      // texture loading failed – keep material empty
    });

  // Handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose primitives
    if (root.userData._primitiveInstances) {
      for (const inst of root.userData._primitiveInstances) {
        if (inst.cleanup) inst.cleanup();
      }
    }
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose texture if loaded
    if (loadedTexture) loadedTexture.dispose();
    // Kill any GSAP timelines (none in this node)
    gsap.globalTimeline.clear();
  };

  return root;
}
